        const double _pr_1 = t111;
        const double _qi_1 = t112;
        zout[2*((size_t)1*Ls + k)] = _pr_1;
        zout[2*((size_t)1*Ls + k) + 1] = _qi_1;
        const double _pr_2 = t109;
        const double _qi_2 = t110;
        zout[2*((size_t)2*Ls + k)] = _pr_2;
