        const double _pr_3 = t106;
        const double _qi_3 = t108;
        zout[2*((size_t)3*Ls + k)] = _pr_3;
        zout[2*((size_t)3*Ls + k) + 1] = _qi_3;
        const double _pr_4 = t102;
